// === Tab: mySketch ===
// For the #WCCChallenge <<Connecting the dots>>

let colors = ['#FFF2D8', '#EAD7BB', '#BCA37F', '#113946', '#fff'];
let noiseGra;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);
	// Noise texture
	noiseGra = createGraphics(windowWidth, windowHeight);
	noiseGra.loadPixels();
	for (let x = 0; x <= width; x++) {
		for (let y = 0; y <= height; y++) {
			noiseGra.set(x, y, color(130, noise(x / 10, y / 10, x * y / 50) * random([0, 20, 50])))
		}
	}
	noiseGra.updatePixels();
}

function draw() {
	// noLoop() removed for animationclear()
	background('#EFDFC9');
	noFill()
	strokeWeight(1)
	stroke(0)
	for (let i = 0; i < 10; i++) {
		drawLine(random(width), random(height))
	}
	image(noiseGra, 0, 0)
	// showFluff(0,0)
}

function drawLine(x, y) {
	for (let j = 0; j < 100; j++) {
		const length = random(100, 500)
		push()
		strokeWeight(random(0.2, 3))
		let clr = color(random(colors))
		clr.setAlpha(int(random(255)))
		stroke(clr)
		translate(x, y)
		scale(random(0.2, 1))
		rotate(random(-PI, PI))
		beginShape()
		curveVertex(0, 0)
		curveVertex(0, 0)
		for (let i = 0; i < 10; i++) {
			curveVertex(length * 0.1 * i, random(-20, 20))
		}
		curveVertex(length, 0)
		curveVertex(length, 0)
		endShape()
		push()
		fill(random(colors))
		ellipse(length, 0, 10)
		ellipse(random(-50, 50), random(-50, 50), 10)
		pop()
		pop()
	}
}
